// Confirmado contra uma resposta real do GET (node 'Buscar lead CVCRM') em
// 18/set/2026: a resposta vem envelopada em {codigo, total, leads: [...]},
// nao o lead direto -- e dentro do lead, 'situacao' e 'corretor' sao objetos
// {id, nome[, email]}, nao campos escalares.
// tipo_evento nao vem em lugar nenhum do payload do CVCRM (o webhook so manda
// idlead) -- se for preciso distinguir o gatilho (criacao vs. mudanca de
// situacao), a saida e cadastrar um Webhook por gatilho no painel do CVCRM,
// cada um com uma query string diferente na URL (ex.: ?gatilho=criacao),
// e ler isso do node 'Webhook CVCRM' original, nao deste.
// TODO: 'empreendimento' veio como array vazio no lead de teste (sem nenhum
// empreendimento vinculado) -- confirmar o formato dos itens (id/nome) contra
// um lead real que tenha empreendimento antes de confiar nesse mapeamento.
//
// origem_campanha invertido em 21/set/2026: quem gerencia campanha e origem
// de lead e o CVCRM, nao o GHL, entao o dono passou a ser cvcrm (ver
// dono_campo). O 'origem' do lead CVCRM ja e uma lista fechada de valores
// padronizados (Facebook, Google, Portais, Painel Gestor etc.), entao o
// valor passa direto pro GHL, sem de-para -- o GHL aceita texto livre.
//
// situacao_lead removido daqui em 22/set/2026: o dono virou ghl (nao cvcrm
// mais), entao mesmo se capturado aqui a view de despacho ignora (dono_campo
// nao bate com origem=cvcrm). Ver situacao_lead em dono_campo.
//
// interacao_cvcrm adicionado 23/set/2026: pega a ULTIMA interacao do array
// (assumindo que vem em ordem cronologica crescente, id/data_cad -- e o que
// foi observado nos testes de 18/set/2026, nunca confirmado formalmente que
// e' sempre assim). So faz sentido quando o gatilho for 'Nova interacao';
// nos outros gatilhos (situacao, corretor), a ultima interacao do array so
// reflete uma anotacao antiga que ja foi sincronizada antes -- o hash de eco
// evita reenvio duplicado quando nao mudou nada.
const lead = ($json.leads ?? [])[0] ?? {};
const interacoes = lead.interacao ?? [];
const ultimaInteracao = interacoes.length ? interacoes[interacoes.length - 1] : null;

return {
  json: {
    origem: 'cvcrm',
    tipo_evento: $('Webhook CVCRM').item.json.query?.gatilho ?? 'desconhecido',
    telefone_bruto: lead.telefone ?? null,
    email_bruto: lead.email ?? null,
    cpf_bruto: lead.documento_tipo === 'cpf' ? (lead.documento ?? null) : null,
    campos: {
      idlead_cvcrm: lead.idlead ?? null,
      corretor_responsavel: lead.corretor?.nome ?? null,
      empreendimento_interesse: lead.empreendimento?.[0]?.nome ?? null,
      origem_campanha: lead.origem ?? null,
      interacao_cvcrm: ultimaInteracao?.descricao ?? null,
    },
  },
};

